def kt(i):
 s=i/6;t=(i+1)/6;v=[0,s,min(1,s+.012),min(1,s+.07),max(s+.07,t-.025),t,1];return ';'.join(f'{x:.4f}'.rstrip('0').rstrip('.') for x in v)
