   w=max(52,round(len(skill)*6.05+20));els.append(f'<rect x="{x}" y="{ys[r]}" width="{w}" height="22" rx="11" fill="{chip}" stroke="url(#accent)" stroke-opacity="{stroke}"/><text x="{x+w/2}" y="{ys[r]+14.8}" text-anchor="middle" fill="{text}" font-size="10.2" font-weight="600">{e(skill)}</text>');x+=w+7
